:root[data-theme="hljs-xt256"] .hljs-link {
  color: #ff00ff !important
}
:root[data-theme="hljs-xt256"] .hljs-meta {
  color: #fff !important;
  font-weight: bolder !important
}
:root[data-theme="hljs-xt256"] :is(.neo-code-preview, .neo-code-preview__content, .neo-code-window, .neo-code-window-content > pre, .neo-editor-input, .json-parser-input, .json-parser-result-wrap) { background: #000000 !important; color: #eaeaea !important; }

:root[data-theme="hljs-xt256"] :is(.neo-code-preview, .neo-code-window, .json-parser-result-wrap) { border-color: hsl(var(--border)) !important; }
:root[data-theme="hljs-xt256"] .json-token-field { color: #00ffff; }
:root[data-theme="hljs-xt256"] .json-token-string { color: #00ff00; }
:root[data-theme="hljs-xt256"] .json-token-number { color: #ff0000; }
:root[data-theme="hljs-xt256"] .json-token-boolean { color: #fff000; }
:root[data-theme="hljs-xt256"] .json-token-null { color: #fff000; }
:root[data-theme="hljs-xt256"] .json-token-punctuation { color: #eaeaea; }
:root[data-theme="hljs-xt256"] .json-parser-type-legend i { background: currentColor; }
